try:
    n = int("abc")
    print(n)
except ValueError:
    print("Not a number")
print("Program continues")

for text in ["5", "x", "0"]:
    try:
        print(10 // int(text))
    except ValueError:
        print("bad number")
    except ZeroDivisionError:
        print("zero!")
    else:
        print("ok")
    finally:
        print("done", text)

